    print("Exiting gracefully...")
    try:
        serial_port.close()
    except Exception as e:
        print(f"Error closing serial port: {e}")
    print("Hardware resources released.")

# Main function
def main():
    global serial_port
    try:
        # Open serial port
        serial_port = serial.Serial(SERIAL_PORT, baudrate=BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to device on {SERIAL_PORT} at {BAUD_RATE} baud.")

        # Signal handler registration
        signal.signal(signal.SIGINT, signal_handler)

        while True:
            try:
                # Read data from the device
                data = serial_port.readline()
                if data:
                    print(f"Received: {data.decode('utf-8')}")
            except TimeoutError:
                print("Device did not respond within timeout.")
            except Exception as e:
                print(f"Error reading from device: {e}")
            except KeyboardInterrupt:
