import time
import gpiozero
import RPi.GPIO as GPIO
import paho.mqtt.client as mqtt
from gpiozero import PWMOutput
from signal import interrupt

# Set up GPIO for BCM 14
try:
    GPIO.setmode(GPIO.BCM)
    pwm_pin = GPIO.PWM(14, frequency=50)  # 50 Hz PWM
    pwm = PWMOutput(pwm_pin)
    pwm.start(0)  # Start with 0 duty cycle
except Exception as e:
    print(f"Error setting up PWM on GPIO 14: {e}")
    exit(1)

def report_state():
    try:
        state = pwm.get_duty_cycle()
        print(f"Current PWM duty cycle: {state}%")
    except ValueError:
        print("Failed to read PWM duty cycle. Check if the device is correctly connected.")
        exit(1)

def on_connect(client, userdata, flags, rc):
    print("Connected with result code "+str(rc))
    client.subscribe("pwm/state")

def on_message(client, userdata, msg):
    print("Received message: ", msg.payload)
    if msg.payload == "toggle":
        if pwm.get_duty_cycle() == 0:
            pwm.start(100)  # Toggle to 100% duty cycle
        else:
            pwm.stop()  # Stop PWM
            pwm.start(0)  # Start with 0 duty cycle

def main():
    mqtt_client = mqtt.Client()
    mqtt_client.on_connect = on_connect
    mqtt_client.on_message = on_message

    try:
        mqtt_client.connect("mqtt.example.com", 1883, 60)
        mqtt_client.loop_forever()
    except KeyboardInterrupt:
        print("Interrupted by user, stopping MQTT and releasing GPIO.")
        mqtt_client.loop_stop()
        pwm.stop()
        GPIO.cleanup()
    except Exception as e:
        print(f"Unexpected error: {e}")
        GPIO.cleanup()

if __name__ == "__main__":
    while True:
        report_state()
        time.sleep(5)

import gpiozero
import time
import paho.mqtt.client as mqtt
import signal

# GPIO configuration
GPIO_PIN = 17  # GPIO 17 (BCM numbering)

# Initialize GPIO with gpiozero
try:
    led = gpiozero.GpioOutput(GPIO_PIN)
    led.value = True  # Start with LED on
except Exception as e:
    print(f"Error initializing GPIO: {e}")
    exit(1)

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")
    client.subscribe("led/state")

def on_message(client, userdata, msg):
    if msg.topic == "led/state":
        try:
            state = msg.payload
            if state == "on":
                led.value = True
                print("LED turned on")
            elif state == "off":
                led.value = False
                print("LED turned off")
            else:
                print("Invalid state command received. Ignoring.")
        except Exception as e:
            print(f"Error processing message: {e}")
            led.value = False  # Reset to safe state

def cleanup():
    try:
        led.value = False  # Turn off LED before closing
        led.cleanup()
    except Exception as e:
        print(f"Error while cleaning up GPIO: {e}")

# MQTT setup
client = mqtt.Client()
client.on_connect = on_connect
client.on_message = on_message
client.connect("mqtt.broker.url", 1883, 60)

signal.signal(signal.SIGINT, cleanup)  # Handle interrupt (Ctrl+C)

try:
    client.loop_forever()
except KeyboardInterrupt:
    pass  # Allow graceful exit on Ctrl+C

# Ensure cleanup on all exit paths
finally:
    try:
        client.disconnect()
        client.loop_stop()
    except Exception as e:
        print(f"Error while disconnecting and stopping MQTT: {e}")

